package ru.main.explorer;
import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
/** Tests the TextureView-space correction, not a second raw-buffer sensor rotation. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CameraTransformTest {
 @Test public void naturalDisplayNeverRotatesOrMirrorsProducerAgain(){for(int sensor:new int[]{0,90,180,270})for(boolean front:new boolean[]{false,true}){Matrix m=CameraActivity.previewMatrix(600,800,1600,1200,sensor,0,front);float[] p={300,400,300,0,600,400};m.mapPoints(p);assertEquals(300,p[0],.01);assertEquals(400,p[1],.01);assertEquals(300,p[2],.01);assertTrue(p[3]<400);assertTrue(p[4]>300);assertEquals(400,p[5],.01);}}
 @Test public void allSensorDisplayFacingCombinationsKeepAspectAndCenter(){for(int sensor:new int[]{0,90,180,270})for(int d:new int[]{0,90,180,270})for(boolean front:new boolean[]{false,true})for(int[] view:new int[][]{{600,800},{800,600},{731,419}}){float w=view[0],h=view[1];Matrix m=CameraActivity.previewMatrix(w,h,1600,1200,sensor,d,front);float[] p={w/2,h/2};m.mapPoints(p);assertEquals(w/2,p[0],.01);assertEquals(h/2,p[1],.01);RectF box=new RectF(0,0,w,h);m.mapRect(box);int r=CameraActivity.relativeRotation(sensor,d,front);float expected=r%180==0?1600f/1200:1200f/1600;assertEquals(expected,box.width()/box.height(),.001);assertTrue(box.left>=-.01&&box.top>=-.01&&box.right<=w+.01&&box.bottom<=h+.01);assertTrue(Math.abs(box.width()-w)<.01||Math.abs(box.height()-h)<.01);float[] axes={0,0,w,0,0,h};m.mapPoints(axes);float cross=(axes[2]-axes[0])*(axes[5]-axes[1])-(axes[3]-axes[1])*(axes[4]-axes[0]);assertTrue("No extra front mirror",cross>0);}}
 @Test public void displayCorrectionHasCorrectDirection(){for(int d:new int[]{0,90,180,270}){Matrix m=CameraActivity.previewMatrix(600,800,1600,1200,90,d,false);float[] p={300,400,300,0};m.mapPoints(p);float dx=p[2]-p[0],dy=p[3]-p[1];if(d==0)assertTrue(dy<0&&Math.abs(dx)<.01);if(d==90)assertTrue(dx<0&&Math.abs(dy)<.01);if(d==180)assertTrue(dy>0&&Math.abs(dx)<.01);if(d==270)assertTrue(dx>0&&Math.abs(dy)<.01);}}
 @Test public void relativeRotationUsesFacingAndDisplayNotJpegDeviceDegrees(){assertEquals(180,CameraActivity.relativeRotation(90,90,false));assertEquals(180,CameraActivity.relativeRotation(270,90,true));assertEquals(0,CameraActivity.jpegRotation(90,270,false));}
}
